<?php
declare(strict_types=1);require_once __DIR__.'/../config/bootstrap.php';$u=require_login();if(!in_array($u['role'],['admin','main_admin'],true)){http_response_code(403);exit('Forbidden');}$pdo=db();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$degree=(int)($_POST['degree_id']??0);$batch=(int)($_POST['batch_id']??0);$year=(int)($_POST['study_year']??0);$sem=(int)($_POST['semester']??0);$q=$pdo->prepare('SELECT d.duration_years FROM academic_degree_intakes adi JOIN academic_degrees d ON d.id=adi.degree_id JOIN academic_batches b ON b.id=adi.batch_id WHERE adi.degree_id=? AND adi.batch_id=? AND adi.is_active=1 AND d.is_active=1 AND b.is_active=1');$q->execute([$degree,$batch]);$duration=(int)$q->fetchColumn();if(!$duration||$year<1||$year>$duration||!in_array($sem,[1,2],true))$error='Invalid intake, year or semester.';else{$pdo->prepare('INSERT INTO academic_intake_progression(degree_id,batch_id,study_year,semester) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE study_year=VALUES(study_year),semester=VALUES(semester)')->execute([$degree,$batch,$year,$sem]);$notice='Intake progression updated for all students in this degree and intake.';}}
$rows=$pdo->query('SELECT adi.degree_id,adi.batch_id,d.name degree_name,d.duration_years,b.batch_code,au.name university_name,COALESCE(p.study_year,1) study_year,COALESCE(p.semester,1) semester FROM academic_degree_intakes adi JOIN academic_degrees d ON d.id=adi.degree_id JOIN awarding_universities au ON au.id=d.awarding_university_id JOIN academic_batches b ON b.id=adi.batch_id LEFT JOIN academic_intake_progression p ON p.degree_id=adi.degree_id AND p.batch_id=adi.batch_id WHERE adi.is_active=1 ORDER BY au.name,d.name,b.batch_code')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Intake progression</title><style>body{font:16px system-ui;background:#f6f7fc;color:#243047;max-width:950px;margin:40px auto;padding:0 18px}article{background:white;border:1px solid #e2e5f1;padding:18px;border-radius:14px;margin:12px 0}form{display:flex;gap:10px;flex-wrap:wrap;align-items:center}select,button{padding:10px;border-radius:8px;border:1px solid #ccd0df}button{background:#6048ce;color:white;border:0;cursor:pointer}a{color:#6048ce}</style>
<script src="<?= htmlspecialchars(url('assets/js/theme-global.js?v=20261107-2'), ENT_QUOTES, 'UTF-8') ?>"></script>
<link rel="stylesheet" href="<?= e(url('assets/css/admin-unified-v1.css?v=1')) ?>">
</head><body><a href="<?= e(url('admin/students.php')) ?>">← Student management</a><h1>Academic intake progression</h1><p>Set the current year and semester once per degree + intake. Students do not select these during registration.</p><?php if($error):?><p><?= e($error) ?></p><?php endif;?><?php if($notice):?><p><?= e($notice) ?></p><?php endif;?><?php foreach($rows as $r):?><article><strong><?= e($r['university_name'].' — '.$r['degree_name'].' — Intake '.$r['batch_code']) ?></strong><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="degree_id" value="<?= (int)$r['degree_id'] ?>"><input type="hidden" name="batch_id" value="<?= (int)$r['batch_id'] ?>"><label>Year <select name="study_year"><?php for($i=1;$i<=(int)$r['duration_years'];$i++):?><option value="<?= $i ?>" <?= $i===(int)$r['study_year']?'selected':'' ?>><?= $i ?></option><?php endfor;?></select></label><label>Semester <select name="semester"><option value="1" <?= (int)$r['semester']===1?'selected':'' ?>>1</option><option value="2" <?= (int)$r['semester']===2?'selected':'' ?>>2</option></select></label><button>Update intake</button></form></article><?php endforeach;?></body></html>
